INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein Sicherheitsprozess immer nur technische Maßnahmen umfasst?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Maßnahmen enthalten"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist zentral für die Risikobewertung in einem Sicherheitsprozess?', 3, '[{"text": "Risikoanalyse", "correct": true, "because": "Identifiziert Bedrohungen"}, {"text": "Softwareinstallation", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zu einem typischen IT-Sicherheitsprozess?', 5, '[{"text": "Risikoanalyse", "correct": true, "because": "Bewertet Bedrohungen"}, {"text": "Maßnahmenumsetzung", "correct": true, "because": "Setzt Schutz um"}, {"text": "Überwachung", "correct": true, "because": "Prüft Wirksamkeit"}, {"text": "Designanpassung", "correct": false, "because": "Kosmetisch"}, {"text": "Bandbreitensteigerung", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Sicherheitsprozess umfasst Schulungen. b) Er ist einmalig und endet nach Umsetzung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Prozess ist kontinuierlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung eines IT-Sicherheitsprozesses?', 4, '[{"text": "Risikobewertung", "correct": false, "because": "Bestimmt Maßnahmen"}, {"text": "Überwachung", "correct": false, "because": "Sichert Kontrolle"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Sicherheitsprozess regelmäßige Audits umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Prüft Wirksamkeit"}, {"text": "Nein", "correct": false, "because": "Audits sind Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme gehört zur Umsetzung eines Sicherheitsprozesses?', 4, '[{"text": "Firewall-Konfiguration", "correct": true, "because": "Schützt Netzwerk"}, {"text": "Schnelle Installation", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Sicherheitsprozess nur für große Unternehmen nötig ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch KMUs brauchen Schutz"}, {"text": "Ja", "correct": false, "because": "Universelle Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Sicherheitsprozess statisch?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierlich angepasst"}, {"text": "Ja", "correct": false, "because": "Dynamische Anpassung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Überwachung eines Sicherheitsprozesses?', 5, '[{"text": "Protokollierung", "correct": true, "because": "Erkennt Vorfälle"}, {"text": "Audits", "correct": true, "because": "Prüfen Maßnahmen"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Planung eines Sicherheitsprozesses?', 4, '[{"text": "Risikoidentifikation", "correct": true, "because": "Bestimmt Maßnahmen"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Farbliche Darstellung", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Sicherheitsprozess schließt Incident Response ein. b) Er ignoriert organisatorische Maßnahmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Organisation wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen effektiven Sicherheitsprozess?', 3, '[{"text": "Risikomanagement", "correct": false, "because": "Bestimmt Schutz"}, {"text": "Protokollierung", "correct": false, "because": "Erkennt Vorfälle"}, {"text": "Dekoratives Layout", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich Sicherheitsvorfälle im Prozess behandle?', 4, '[{"text": "Mit Incident Response Plan", "correct": true, "because": "Definiert Reaktion"}, {"text": "Nur ignorieren", "correct": false, "because": "Erhöht Schaden"}, {"text": "Ohne Plan reagieren", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Sicherheitsprozess automatisch läuft. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Erfordert aktive Steuerung"}, {"text": "Ja", "correct": false, "because": "Manuelle Überwachung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip verbessert die Wirksamkeit eines Sicherheitsprozesses?', 4, '[{"text": "Kontinuierliche Verbesserung", "correct": true, "because": "Passt an Bedrohungen an"}, {"text": "Einmalige Umsetzung", "correct": false, "because": "Zu statisch"}, {"text": "Minimale Kontrolle", "correct": false, "because": "Ineffektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Umfasst ein Sicherheitsprozess nur technische Lösungen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Maßnahmen"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gehören zur Umsetzung eines Sicherheitsprozesses?', 5, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Daten"}, {"text": "Zugriffskontrollen", "correct": true, "because": "Begrenzen Zugriff"}, {"text": "Bunte Interfaces", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Sicherheitsprozess unwichtig?', 3, '[{"text": "Audits", "correct": false, "because": "Prüfen Wirksamkeit"}, {"text": "Schulungen", "correct": false, "because": "Erhöhen Bewusstsein"}, {"text": "Präsentationsstil", "correct": true, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich einen Sicherheitsprozess etabliere?', 4, '[{"text": "Risiken analysieren, Maßnahmen umsetzen", "correct": true, "because": "Strukturierter Ansatz"}, {"text": "Nur Firewall einrichten", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Plan starten", "correct": false, "because": "Unstrukturiert"}]');
